    area=occ.getMass(2,tag); com=occ.getCenterOfMass(2,tag); box=gmsh.model.getBoundingBox(2,tag); dx=box[3]-box[0]
    if area>1e-4: fb_s.append(tag)
    elif area>5.5e-6 and dx<1e-6: (in_s if com[0]<L/2 else out_s).append(tag)
